module barrel_shifter (
    input [7:0] in,
    input [2:0] ctrl,
    output [7:0] out
);

wire [7:0] stage1_out;
wire [7:0] stage2_out;

assign stage1_out = (ctrl[2]) ? {in[3:0], 4'b0} : in;

assign stage2_out = (ctrl[1]) ? {stage1_out[5:0], 2'b0} : stage1_out;

assign out = (ctrl[0]) ? {stage2_out[6:0], 1'b0} : stage2_out;

endmodule

module mux2X1( in0,in1,sel,out);
input in0,in1;
input sel;
output out;
assign out=(sel)?in1:in0;
endmodule
